mapper.update:
update orders
status = #{status}, pay_time = now(), delivery_time = now(), finish_time = now(), cancel_time = now(), update_time = now()
where id = #{id} and status = #{currentStatus}

mapper.select:
select count(*) from orders

    and status = #{status}
    and pay_method = #{payMethod}
    and user_id = #{userId}

select * from orders

    and status = #{orderPageQueryDTO.status}
    and pay_method = #{orderPageQueryDTO.payMethod}
    and user_id = #{orderPageQueryDTO.userId}

order by id asc limit #{begin},#{orderPageQueryDTO.pageSize}

select * from orders
where user_id = #{orderPageQueryDTO.userId}
order by id asc
